code='#!/usr/bin/env python3\n"""\nOrchestrator script for X‑ray diffraction orientation matrix indexing.\nImports all supplied modules, resolves dependencies, and runs the pipeline.\n"""\n\nimport sys\nimport os\nimport numpy as np\n\n# Add the sandbox directory to path\nsandbox_dir = "/Users/leonid/Desktop/FusionAI/scitracer/sandbox"\nif sandbox_dir not in sys.path:\n    sys.path.insert(0, sandbox_dir)\n\n# Import all modules (skip step_04 because it is None)\nimport step_00_step_1_compute_b_matrix as step00\nimport step_01_step_2_compute_q_vectors_from_detector_p as step01\nimport step_02_step_3_determine_candidate_indices_for_q as step02\nimport step_03_step_4_compute_candidate_u_matrices as step03\nimport step_05_step_6_return_results as step05\n\n# ----------------------------------------------------------------------\n# Coherence check: compare B matrices from step00 and step05\n# ----------------------------------------------------------------------\nprint("=" * 70)\nprint("COHERENCE CHECK: B‑matrix definitions")\nprint("=" * 70)\n\n# Lattice parameters (cubic Al, a=4.05 Å)\na, b, c = 4.05, 4.05, 4.05\nalpha, beta, gamma = 90.0, 90.0, 90.0\nlattice_params = (a, b, c, alpha, beta, gamma)\n\nB_step00 = step00.compute_B(lattice_params)\nB_step05 = step05.compute_B_matrix(a, b, c, alpha, beta, gamma)\n\nprint("\\nB from step_00 (without 2π factor):")\nprint(B_step00)\nprint("\\nB from step_05 (includes 2π factor):")\nprint(B_step05)\n\n# They should satisfy B_step05 ≈ 2π * B_step00\nprint("\\nComparison: B_step05 vs 2π * B_step00")\nprint("2π * B_step00:")\nprint(2 * np.pi * B_step00)\nassert np.allclose(B_step05, 2 * np.pi * B_step00, atol=1e-10), "B matrices not consistent by 2π factor"\nprint("✓ Coherence check passed: B_step05 = 2π * B_step00\\n")\n\n# ----------------------------------------------------------------------\n# Step 01: Compute Q vectors from dummy detector data\n# ----------------------------------------------------------------------\nprint("-" * 70)\nprint("Step 01: Compute Q vectors from detector pixels")\nprint("-" * 70)\n\n# Define dummy peaks (x_pixel, y_pixel, frame) for three reflections\n# For demonstration we use pixels that would correspond to known reflections.\n# We will not enforce physical accuracy; we just test the function.\npeaks = [(500.0, 500.0, 1), (600.0, 500.0, 1), (500.0, 600.0, 1)]\ndetector_params = {\n    \'wavelength\': 0.71,       # Mo Kα (Å)\n    \'distance\': 200.0,        # mm\n    \'pix_size_x\': 0.172,      # mm\n    \'pix_size_y\': 0.172,      # mm\n    \'beam_center_x\': 500.0,   # pixels\n    \'beam_center_y\': 500.0    # pixels\n}\n\nQ_vectors_step01 = step01.compute_Q_vectors(peaks, detector_params)\nprint("\\nComputed Q vectors (Å⁻¹):")\nfor i, Q in enumerate(Q_vectors_step01):\n    print(f"  Q{i+1}: {Q}")\n\n# ----------------------------------------------------------------------\n# Step 02: Candidate indices using B from step00 (no 2π)\n# ----------------------------------------------------------------------\nprint("-" * 70)\nprint("Step 02: Candidate indices for Q1 and Q2 (using B_step00)")\nprint("-" * 70)\n\n# We need Q vectors that are consistent with B_step00 (no 2π).\n# For demonstration we generate Q from known indices using B_step00.\n# This avoids scaling mismatch and tests the function correctly.\nh1_true = (1, 0, 0)\nh2_true = (0, 1, 0)\nh3_true = (1, 1, 1)\n\nQ1_for_step02 = B_step00 @ np.array(h1_true, dtype=float)\nQ2_for_step02 = B_step00 @ np.array(h2_true, dtype=float)\nQ3_for_step02 = B_step00 @ np.array(h3_true, dtype=float)\n\nH1_candidates = step02.candidate_indices(Q1_for_step02, B_step00, tolerance=0.01, max_index=5)\nH2_candidates = step02.candidate_indices(Q2_for_step02, B_step00, tolerance=0.01, max_index=5)\n\nprint(f"\\nCandidate indices for Q1 (true = {h1_true}):")\nprint(f"  Found {len(H1_candidates)} candidates")\nfor hkl in H1_candidates[:5]:\n    print(f"    {hkl}")\nprint(f"\\nCandidate indices for Q2 (true = {h2_true}):")\nprint(f"  Found {len(H2_candidates)} candidates")\nfor hkl in H2_candidates[:5]:\n    print(f"    {hkl}")\n\n# ----------------------------------------------------------------------\n# Step 03: Compute candidate U matrices\n# ----------------------------------------------------------------------\nprint("-" * 70)\nprint("Step 03: Candidate U matrices (using B_step00)")\nprint("-" * 70)\n\n# Convert list of tuples to list of arrays as expected by step03\nH1_arr = [np.array(h, dtype=float) for h in H1_candidates]\nH2_arr = [np.array(h, dtype=float) for h in H2_candidates]\n\ncandidates = step03.compute_candidate_U(H1_arr, H2_arr, Q1_for_step02, Q2_for_step02, B_step00)\nprint(f"\\nFound {len(candidates)} valid U candidates")\n\n# ----------------------------------------------------------------------\n# Step 05: Full indexing pipeline (using its own consistent definitions)\n# ----------------------------------------------------------------------\nprint("=" * 70)\nprint("Step 05: Full indexing (index_crystal)")\nprint("=" * 70)\n\n# For step05 we need Q vectors that match its B (includes 2π).\n# We generate them from the known indices using B_step05.\nQ1_step05 = B_step05 @ np.array(h1_true, dtype=float)\nQ2_step05 = B_step05 @ np.array(h2_true, dtype=float)\nQ3_step05 = B_step05 @ np.array(h3_true, dtype=float)\n\n# Add small noise to simulate experimental data (as in step05 example)\nnp.random.seed(42)\nnoise = 0.005\nQ1_noisy = Q1_step05 + np.random.normal(0, noise, 3)\nQ2_noisy = Q2_step05 + np.random.normal(0, noise, 3)\nQ3_noisy = Q3_step05 + np.random.normal(0, noise, 3)\n\ntry:\n    result = step05.index_crystal(a, b, c, alpha, beta, gamma,\n                                  Q1_noisy, Q2_noisy, Q3_noisy,\n                                  tolerance=0.02, max_hkl=3)\n    U_best, h1_best, h2_best, h3_best = result\n    print("\\nBest orientation matrix U:")\n    print(U_best)\n    print("\\nIndices:")\n    print(f"  Q1 -> {h1_best} (true {h1_true})")\n    print(f"  Q2 -> {h2_best} (true {h2_true})")\n    print(f"  Q3 -> {h3_best} (true {h3_true})")\n    print("\\n✓ Indexing successful")\nexcept Exception as e:\n    print(f"Indexing failed: {e}")\n\n# ----------------------------------------------------------------------\n# Final note: all modules were called\n# ----------------------------------------------------------------------\nprint("\\n" + "=" * 70)\nprint("All modules imported and called. Orchestration complete.")\nprint("=" * 70)'